24|    execFileSync('git', ['init', '-q'], { cwd: repoRoot });
25|    execFileSync('git', ['config', 'user.email', 'test@test'], { cwd: repoRoot });
26|    execFileSync('git', ['config', 'user.name', 'test'], { cwd: repoRoot });
27|    await writeFile(join(repoRoot, 'placeholder.txt'), 'x\n');
28|    execFileSync('git', ['add', '.'], { cwd: repoRoot });
29|    execFileSync('git', ['commit', '-qm', 'init'], { cwd: repoRoot });
30|
31|    const commit = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: repoRoot }).toString().trim();
32|    const mkNode = (id, file, line) => ({
33|      id,
34|      type: 'Function',
35|      label: id,
36|      file_path: file,
37|      start_line: line,
38|      end_line: line,
39|      language: 'cpp',
40|      confidence: 1,
41|      structural_fp: '',
42|      dependency_fp: '',
43|      extra: { qname: id },
44|    });
45|
46|    for (const node of [
47|      mkNode('renderScene', 'src/renderScene.cpp', 1),
48|      mkNode('renderChunk', 'src/renderChunk.cpp', 10),
49|      mkNode('LodMeshRenderer', 'src/LodMeshRenderer.cpp', 20),
50|      mkNode('inspectQueryHelper', 'src/inspectQueryHelper.cpp', 30),
51|      mkNode('handleQueryInspectCommands', 'src/handleQueryInspectCommands.cpp', 40),
52|    ]) {
53|      upsertNode(db, node);
54|    }
55|
56|    const edge = (from, to, line) => ({
57|      from_id: from,
58|      to_id: to,
59|      relation: 'CALLS',
60|      source_file: `src/${from}.cpp`,
61|      source_line: line,
62|      confidence: 0.95,
63|      provenance: 'EXTRACTED',
64|      extractor: 'test',
65|    });
66|
67|    upsertEdge(db, edge('renderChunk', 'LodMeshRenderer', 10));
68|    upsertEdge(db, edge('renderScene', 'renderChunk', 20));
69|    upsertEdge(db, edge('renderChunk', 'inspectQueryHelper', 30));
70|    upsertEdge(db, edge('handleQueryInspectCommands', 'LodMeshRenderer', 40));
71|
72|    await writeFile(join(graphDir, 'manifest.json'), JSON.stringify({
73|      status: 'ok',
74|      commit,
75|      indexedAt: new Date().toISOString(),
76|      nodes: 5,
77|      edges: 4,
78|      schemaVersion: SCHEMA_VERSION,
79|      extractorVersion: EXTRACTOR_VERSION,
80|      parserBundleVersion: PARSER_BUNDLE_VERSION,
81|      dirtyFiles: [],
82|      dirtyEdges: [],
83|      dirtyEdgeCount: 0,
84|      trustDirtyEdgeCount: 0,
85|    }));
86|  });
87|
88|  afterEach(async () => {
89|    try { db.close(); } catch {}
90|    await rm(repoRoot, { recursive: true, force: true });
91|  });
92|
93|  it('graph_callers(depth>1) only returns edges that stay on the recursive caller chain', async () => {
94|    const out = await graphCallers({ repoRoot, symbol: 'LodMeshRenderer', depth: 2, top_k: 20 });
95|    expect(out).toContain('renderChunk');
96|    expect(out).toContain('renderScene');
97|    expect(out).not.toContain('inspectQueryHelper');
98|  });
99|
100|  it('graph_callees(depth>1) only returns edges that stay on the recursive callee chain', async () => {
101|    const out = await graphCallees({ repoRoot, symbol: 'renderScene', depth: 2, top_k: 20 });
102|    expect(out).toContain('renderChunk');
103|    expect(out).toContain('LodMeshRenderer');
104|    expect(out).not.toContain('handleQueryInspectCommands');
105|  });
