44|/** A repo where `callerCount` distinct functions each call one target. */
45|async function fanInRepo(callerCount) {
46|  const r = await mkdtemp(join(tmpdir(), 'apg-cap-'));
47|  await mkdir(join(r, '.aify-graph'), { recursive: true });
48|  execFileSync('git', ['-C', r, 'init', '-q'], { stdio: 'ignore' });
49|  execFileSync('git', ['-C', r, '-c', 'user.email=t@t', '-c', 'user.name=t', 'commit', '--allow-empty', '-qm', 'i'], { stdio: 'ignore' });
50|  const commit = execFileSync('git', ['-C', r, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
51|  await writeFile(join(r, '.aify-graph', 'manifest.json'), JSON.stringify({
52|    commit, indexedAt: new Date().toISOString(), nodes: callerCount + 1, edges: callerCount,
53|    schemaVersion: 4, extractorVersion: '0.1.0', status: 'ok',
54|    dirtyFiles: [], dirtyEdges: [], dirtyEdgeCount: 0,
55|  }));
56|  const db = openDb(join(r, '.aify-graph', 'graph.sqlite'));
57|  const node = (id, label) => db.run(
58|    `INSERT INTO nodes (id,type,label,file_path,start_line,end_line,language,confidence,extra)
59|     VALUES ('${id}','Function','${label}','src/a.js',1,2,'javascript',1,'{}')`);
60|  node('t', 'target');
61|  for (let i = 0; i < callerCount; i += 1) {
62|    node(`c${i}`, `caller${i}`);
63|    // ⚠ One edge per (from,to,relation): the edges table carries a UNIQUE index on exactly that
64|    // triple, so distinct callers are the only way to build a fan-in of a given size.
65|    db.run(`INSERT INTO edges (from_id,to_id,relation,source_file,source_line,confidence,provenance,extractor)
66|            VALUES ('c${i}','t','CALLS','src/a.js',${i + 10},0.9,'EXTRACTED','test')`);
67|  }
68|  db.close();
69|  return r;
