2|  INSERT OR IGNORE INTO edges (from_id, to_id, relation, source_file, source_line, confidence, provenance, extractor)
3|  VALUES ($from_id, $to_id, $relation, $source_file, $source_line, $confidence, $provenance, $extractor)
4|`;
5|
6|const CODE_INTEL_OVERRIDE_SQL = `
7|  UPDATE edges
8|  SET source_file = $source_file,
9|      source_line = $source_line,
10|      confidence = $confidence,
11|      provenance = $provenance,
12|      extractor = $extractor
13|  WHERE from_id = $from_id
14|    AND to_id = $to_id
15|    AND relation = $relation
16|    AND provenance != 'CODE_INTEL'
17|`;
18|
19|export function upsertEdge(db, edge) {
20|  const params = {
21|    from_id: edge.from_id,
22|    to_id: edge.to_id,
23|    relation: edge.relation,
24|    source_file: edge.source_file ?? '',
25|    source_line: edge.source_line ?? 0,
26|    confidence: edge.confidence ?? 1.0,
27|    provenance: edge.provenance ?? 'EXTRACTED',
28|    extractor: edge.extractor ?? 'generic',
29|  };
30|  const info = db.run(INSERT_SQL, params);
31|  if (info.changes === 0 && params.provenance === 'CODE_INTEL') {
32|    db.run(CODE_INTEL_OVERRIDE_SQL, params);
33|  }
34|}
35|
36|export function listEdges(db, filter = {}) {
37|  const clauses = [];
38|  const params = {};
39|  if (filter.from_id) { clauses.push('from_id = $from_id'); params.from_id = filter.from_id; }
40|  if (filter.to_id) { clauses.push('to_id = $to_id'); params.to_id = filter.to_id; }
41|  if (filter.relation) { clauses.push('relation = $relation'); params.relation = filter.relation; }
42|  if (filter.source_file) { clauses.push('source_file = $source_file'); params.source_file = filter.source_file; }
43|
44|  const where = clauses.length ? `WHERE ${clauses.join(' AND ')}` : '';
45|  return db.all(`SELECT * FROM edges ${where}`, params);
46|}
47|
48|export function deleteEdgesFrom(db, fromId, relation) {
49|  if (relation) {
50|    db.run('DELETE FROM edges WHERE from_id = $from_id AND relation = $relation',
51|      { from_id: fromId, relation });
52|  } else {
53|    db.run('DELETE FROM edges WHERE from_id = $from_id', { from_id: fromId });
54|  }
55|}
56|
57|export function deleteEdgesTo(db, toId, relation) {
58|  if (relation) {
59|    db.run('DELETE FROM edges WHERE to_id = $to_id AND relation = $relation',
60|      { to_id: toId, relation });
61|  } else {
62|    db.run('DELETE FROM edges WHERE to_id = $to_id', { to_id: toId });
63|  }
64|}
